DESIGN = json.loads('{"task_id": "STAGE20-LABELS", "contract_version": 1, "cases": [{"id": "empty_input", "intent": "Rule 10: empty input emits no labels.", "input": "", "expected": []}, {"id": "empty_segments", "intent": "Rules 1, 2, 5, 6, 9: repeated separators, empty quotes and ordinary-only labels disappear.", "input": ",, \\t\\r\\n\\u000b\\f,\\"\\", \\"\\" ,,,", "expected": []}, {"id": "order_and_ascii_case", "intent": "Rules 1, 8, 10: lowercase and retain the first occurrence order across repeated separators.", "input": ",ZETA,,Alpha,BETA,zeta,ALPHA,,Gamma,", "expected": ["zeta", "alpha", "beta", "gamma"]}, {"id": "quote_concatenation", "intent": "Rules 2, 8, 10: quotes toggle anywhere, concatenate segments, and do not protect uppercase from lowercasing.", "input": "AB\\"CD\\"EF\\"GH\\",\\"AB\\"CD\\"EF\\"GH,A\\"\\"B,\\"\\"X\\"\\"", "expected": ["abcdefgh", "ab", "x"]}, {"id": "quoted_commas", "intent": "Rules 1, 2, 8: commas inside quotes remain literal, including adjacent commas and a comma-only label.", "input": "A\\"B,C\\"D,\\"E,,F\\",\\",\\",G", "expected": ["ab,cd", "e,,f", ",", "g"]}, {"id": "escapes_outside_quotes", "intent": "Rules 1, 3, 8: escaped comma, quote and backslash are literal outside quotes; escaped uppercase is lowercased.", "input": "A\\\\,B,C\\\\\\"D,E\\\\\\\\F,\\\\G", "expected": ["a,b", "c\\"d", "e\\\\f", "g"]}, {"id": "escapes_inside_quotes", "intent": "Rules 2, 3, 8: escaped comma, quote, backslash and uppercase work inside quotes without toggling mode.", "input": "\\"A\\\\,B\\\\\\"C\\\\\\\\D\\\\E\\",TAIL", "expected": ["a,b\\"c\\\\de", "tail"]}, {"id": "all_ordinary_whitespace", "intent": "Rules 5, 6, 8: all six ordinary ASCII whitespace characters trim at boundaries and collapse internally.", "input": " \\t\\r\\n\\u000b\\fA \\t\\r\\n\\u000b\\fB\\f\\u000b\\n\\r\\t ,C\\tD\\rE\\nF\\u000bG\\fH I", "expected": ["a b", "c d e f g h i"]}, {"id": "all_quoted_whitespace", "intent": "Rules 5, 7, 8: quoted whitespace preserves all six characters and multiplicity at both boundaries and internally.", "input": "\\" \\t\\r\\n\\u000b\\fA  \\t\\t\\r\\n\\u000b\\fB\\f\\u000b\\n\\r\\t \\"", "expected": [" \\t\\r\\n\\u000b\\fa  \\t\\t\\r\\n\\u000b\\fb\\f\\u000b\\n\\r\\t "]}, {"id": "all_escaped_whitespace", "intent": "Rules 3, 5, 7, 9: individually escaped instances of all six whitespace characters remain a nonempty exact label.", "input": "\\\\ \\\\\\t\\\\\\r\\\\\\n\\\\\\u000b\\\\\\f\\\\ ", "expected": [" \\t\\r\\n\\u000b\\f "]}, {"id": "protected_boundaries", "intent": "Rules 6, 7, 8: trim only ordinary outer whitespace and stop trimming at protected whitespace.", "input": " \\t\\"  A  \\"\\r\\n,  \\\\ B\\\\  \\t, \\" \\" \\tA\\t \\" \\" ", "expected": ["  a  ", " b "]}, {"id": "protected_breaks_runs", "intent": "Rules 6, 7: protected whitespace interrupts ordinary runs, so each neighboring ordinary run contributes its own space.", "input": "A \\t\\"\\t\\t\\"\\r\\n B,A  \\\\  \\t B", "expected": ["a \\t\\t b", "a   b"]}, {"id": "empty_quotes_do_not_break_runs", "intent": "Rules 2, 6, 9, 10: removed empty quotes emit no protected character and do not interrupt ordinary whitespace runs.", "input": "A \\"\\"\\t B, A\\t B ,\\"\\" \\t\\"\\",A\\"\\"B", "expected": ["a b", "ab"]}, {"id": "protected_only_and_exact_dedup", "intent": "Rules 7, 9, 10: protected-only whitespace survives; equality uses exact final characters and multiplicity.", "input": " ,\\" \\" ,\\\\ ,\\"  \\",\\"\\t\\",\\\\\\t,\\" \\t\\",\\"\\"", "expected": [" ", "  ", "\\t", " \\t"]}, {"id": "dedup_after_normalization", "intent": "Rules 2, 3, 6, 7, 8, 10: distinct syntax normalizes to equal labels while extra protected whitespace remains distinct.", "input": "B, A\\t C ,\\"A C\\",A\\\\ C,a  c,\\"A  C\\",b,D,\\"a  c\\"", "expected": ["b", "a c", "a  c", "d"]}, {"id": "other_ascii_literals", "intent": "Rules 5, 8: preserve punctuation, single quotes, digits and ASCII controls outside the six whitespace characters.", "input": " \'AZ_09-!?:;[]{}()/+=.@#$%^&*|~`\' ,\\u0000A\\u001cB\\u001dC\\u001eD\\u001fE\\u007f", "expected": ["\'az_09-!?:;[]{}()/+=.@#$%^&*|~`\'", "\\u0000a\\u001cb\\u001dc\\u001ed\\u001fe\\u007f"]}, {"id": "escape_exactly_one_whitespace", "intent": "Rules 3, 6, 7: an escape protects exactly one character; following ordinary boundary whitespace is trimmed.", "input": "\\\\  \\t, \\t\\\\ ,A\\\\\\t\\t\\tB,\\\\\\n\\n", "expected": [" ", "a\\t b", "\\n"]}, {"id": "escaped_backslash_then_separator", "intent": "Rules 1, 3: an escaped backslash does not escape the following comma; an escaped comma can then combine with a literal backslash.", "input": "A\\\\\\\\,B,C\\\\\\\\\\\\,D", "expected": ["a\\\\", "b", "c\\\\,d"]}, {"id": "escaped_quote_then_real_toggle", "intent": "Rules 1, 2, 3, 8: an escaped quote is emitted, while the next unescaped quote still toggles mode and protects a comma.", "input": "A\\\\\\"\\"B,C\\"D,\\"E\\\\\\"\\"F,G", "expected": ["a\\"b,cd", "e\\"f", "g"]}, {"id": "trailing_escape_outside", "intent": "Rule 4: a trailing unpaired backslash outside quotes invalidates the whole input after valid labels.", "input": "GOOD,\\"ALSO GOOD\\",BAD\\\\", "expected": null}, {"id": "trailing_escape_inside", "intent": "Rules 3, 4: a trailing unpaired backslash inside an unclosed quote invalidates all preceding valid labels.", "input": "GOOD,OK,\\"BAD\\\\", "expected": null}, {"id": "unclosed_quote_mid_label", "intent": "Rules 2, 4: an unclosed quote beginning mid-label invalidates preceding valid labels even when suffix commas are quoted.", "input": "GOOD,SECOND,PRE\\"BAD,TAIL", "expected": null}, {"id": "escaped_final_quote_is_not_closing", "intent": "Rules 3, 4: an escaped final quote remains literal and cannot close quoted mode; the whole input fails.", "input": "GOOD,\\"BAD\\\\\\"", "expected": null}], "properties": ["unique_nonempty_labels", "ascii_lowercase"], "rationale": "The 23 deterministic ASCII cases cover all ten rules. Separators and concatenated quote segments exercise scanning; both modes escape commas, quotes, backslashes and uppercase. All six whitespace characters are tested as ordinary, quoted and escaped, including boundaries, multiplicity and interrupted runs. Empty quotes do not introduce provenance. Exact final-string deduplication is checked across syntactically different labels and protected whitespace distinctions. Other ASCII characters remain literal. Four malformed suffixes require whole-input ValueError after valid labels. Expectations are derived from per-character quote/escape provenance, boundary trimming, ordinary-run collapse, ASCII lowercasing, empty removal and stable exact deduplication."}')
results=[]; properties=[]; interface=True
s=inspect.signature(normalize_labels)
interface=(list(s.parameters)==['value'] and s.parameters['value'].annotation in (str,'str') and s.return_annotation in (list[str],'list[str]'))
for c in DESIGN['cases']:
    actual=None; error=None
    try: actual=normalize_labels(c['input'])
    except Exception as exc: error=type(exc).__name__
    passed=(error=='ValueError') if c['expected'] is None else (error is None and type(actual) is list and actual==c['expected'])
    results.append({'id':c['id'],'input':c['input'],'expected':c['expected'],'actual':actual,'error':error,'passed':passed})
    if error is None and type(actual) is list:
        for prop in DESIGN['properties']:
            ok=(all(type(x) is str and x!='' for x in actual) and len(actual)==len(set(actual))) if prop=='unique_nonempty_labels' else all(type(x) is str and not any('A'<=ch<='Z' for ch in x) for x in actual)
            properties.append({'case':c['id'],'property':prop,'passed':ok})
passed=interface and all(c['passed'] for c in results) and all(c['passed'] for c in properties)
print(json.dumps({'passed':passed,'interface':interface,'cases':results,'properties':properties},ensure_ascii=True))
